"""The windows a measurement can raise, and the sound each one plays.

Knut asked for this as a table the user can actually read (#131, 2026-07-27):
*"a full table like this one shall be added to the help text icon ... Make sure
the table is actually shown as a table, for example using html table in the help
icon window."*

It lives here rather than inline so one text can be shown from more than one help
icon, and so a test can hold it against the code it describes. The sound names
are the ones in Preferences -> Sounds, never the internal identifiers (Knut:
"Patch out of tolerance: There is no sound defined with this name").
"""
from __future__ import annotations

from core.i18n import tr

#: Rows of the windows table: (window, reading mode, Preferences sound label).
WINDOW_ROWS = [('Strip read failed', 'Strip reading', "Slow down, or Strip read failed — ChromIQ reads Argyll's own wording and picks the one that fits"), ('Patch read failed', 'Patch by patch', 'Strip read failed'), ('Strip read quickly', 'Strip reading', 'Slow down'), ('Wrong strip read', 'Strip reading', 'Strip read failed'), ('Unexpected Color Response', 'Both', 'Patch reading looks off'), ('Strip may be misaligned', 'Strip reading', 'Strip read failed'), ('Strip read interrupted', 'Strip reading', 'Strip read failed'), ('Patches still unread', 'Both', 'Strip read failed'), ('Calibration required', 'Both', 'Instrument error'), ('Confirm abort', 'Both', 'Instrument error'), ('Instrument disconnected', 'Both', 'Instrument error'), ('No instrument found', 'Both', 'Instrument error'), ('Instrument busy', 'Both', 'Instrument error'), ('Instrument in Wrong Position', 'Both', 'Instrument error'), ('Instrument Not Accessible (claimed by a virtual machine)', 'Both', 'Instrument error'), ('Instrument error (other)', 'Both', 'Instrument error'), ('All strips read / All patches read', 'Both', 'Measurement finished')]

#: Sounds that mark an event rather than a window.
EVENT_ROWS = [('A patch was read and looks right', 'Patch by patch', 'Patch read OK'), ('A patch was read and looks off', 'Patch by patch', 'Patch reading looks off'), ('A strip was accepted', 'Strip reading', 'Strip read OK'), ('A strip was accepted but read quickly', 'Strip reading', 'Slow down'), ('The measurement finished', 'Both', 'Measurement finished'), ('A profile finished building', '—', 'Profile build finished')]


def windows_and_sounds_html() -> str:
    """The table as HTML. :class:`ui.tooltip_button.TooltipButton` switches to
    rich text when a body contains one."""
    return tr('<p>Every window a measurement can raise, and the sound played <b>as it opens</b> — not when you answer it. The names in the last column are the ones in Preferences &rarr; Sounds, so you can change any of them there.</p>\n\n<table border="1" cellspacing="0" cellpadding="6">\n<tr><th>#</th><th>Window</th><th>Reading mode</th><th>Sound played when it opens</th></tr>\n<tr><td>1</td><td>Strip read failed</td><td>Strip reading</td><td>Slow down, or Strip read failed — ChromIQ reads Argyll\'s own wording and picks the one that fits</td></tr>\n<tr><td>2</td><td>Patch read failed</td><td>Patch by patch</td><td>Strip read failed</td></tr>\n<tr><td>3</td><td>Strip read quickly</td><td>Strip reading</td><td>Slow down</td></tr>\n<tr><td>4</td><td>Wrong strip read</td><td>Strip reading</td><td>Strip read failed</td></tr>\n<tr><td>5</td><td>Unexpected Color Response</td><td>Both</td><td>Patch reading looks off</td></tr>\n<tr><td>6</td><td>Strip may be misaligned</td><td>Strip reading</td><td>Strip read failed</td></tr>\n<tr><td>7</td><td>Strip read interrupted</td><td>Strip reading</td><td>Strip read failed</td></tr>\n<tr><td>8</td><td>Patches still unread</td><td>Both</td><td>Strip read failed</td></tr>\n<tr><td>9</td><td>Calibration required</td><td>Both</td><td>Instrument error</td></tr>\n<tr><td>10</td><td>Confirm abort</td><td>Both</td><td>Instrument error</td></tr>\n<tr><td>11</td><td>Instrument disconnected</td><td>Both</td><td>Instrument error</td></tr>\n<tr><td>12</td><td>No instrument found</td><td>Both</td><td>Instrument error</td></tr>\n<tr><td>13</td><td>Instrument busy</td><td>Both</td><td>Instrument error</td></tr>\n<tr><td>14</td><td>Instrument in wrong position</td><td>Both</td><td>Instrument error</td></tr>\n<tr><td>15</td><td>USB claimed by a virtual machine</td><td>Both</td><td>Instrument error</td></tr>\n<tr><td>16</td><td>Instrument error (other)</td><td>Both</td><td>Instrument error</td></tr>\n<tr><td>17</td><td>All strips read / All patches read</td><td>Both</td><td>Measurement finished</td></tr>\n</table>\n\n<p><b>Sounds that are not windows</b> — these mark an event as it happens.</p>\n\n<table border="1" cellspacing="0" cellpadding="6">\n<tr><th>#</th><th>Event</th><th>Reading mode</th><th>Sound</th></tr>\n<tr><td>1</td><td>A patch was read and looks right</td><td>Patch by patch</td><td>Patch read OK</td></tr>\n<tr><td>2</td><td>A patch was read and looks off</td><td>Patch by patch</td><td>Patch reading looks off</td></tr>\n<tr><td>3</td><td>A strip was accepted</td><td>Strip reading</td><td>Strip read OK</td></tr>\n<tr><td>4</td><td>A strip was accepted but read quickly</td><td>Strip reading</td><td>Slow down</td></tr>\n<tr><td>5</td><td>The measurement finished</td><td>Both</td><td>Measurement finished</td></tr>\n<tr><td>6</td><td>A profile finished building</td><td>—</td><td>Profile build finished</td></tr>\n</table>\n\n<p><b>Two things worth knowing.</b> The completion sound waits half a second so the last strip\'s own cue can finish first — they used to arrive on top of each other. And ChromIQ plays none of these while stock ArgyllCMS chartread is doing the reading: it beeps for itself there and cannot be silenced, so ChromIQ would only double every event. On ChromIQ\'s own reading engine, Argyll\'s beeps are silenced and these sounds are the only ones you hear.</p>')
